int
hypre_SeqVectorSetConstantValues( hypre_Vector *v,
                               double        value )
{
   double  *vector_data = hypre_VectorData(v);
   int      size        = hypre_VectorSize(v);

   int      i;

   int      ierr  = 0;

   size *=hypre_VectorNumVectors(v);


