inline double firstRepeatOffsetProb(const double probMult, const int maxRepeatOffset) {
  if (probMult < 1 || probMult > 1)
    return (1 - probMult) / (1 - pow(probMult, (double)maxRepeatOffset));
  else
    return 1.0 / maxRepeatOffset;
}

