    unsigned char *seqBeg,
    const float *probabilities,
    const unsigned char *maskTable) {

  const double minMaskProb = 0.5;
  for (int i=0; i<size; i++)
    if (probabilities[i] >= minMaskProb)
      seqBeg[i] = maskTable[seqBeg[i]];
