            for (int j = 0; j < D; ++j) {
              local_data[local_row + j] = 0;
            }
            valid_data[lid] = 0;
          }
          if (tid_in_tile < N) {
            #pragma omp barrier
          }
          for (int i = 0; i < TILE_WIDTH; ++i) {
            int local_row_tile = i * D;
